@Component
public class OrderSagaOrchestrator {

    private final OrderServiceClient orderService;
    private final InventoryServiceClient inventoryService;
    private final PaymentServiceClient paymentService;

    public OrderSagaOrchestrator(OrderServiceClient o, InventoryServiceClient i, PaymentServiceClient p) {
        this.orderService = o;
        this.inventoryService = i;
        this.paymentService = p;
    }

    public void executeOrderWorkflow(CreateOrderCommand cmd) {
        String orderId = orderService.createPendingOrder(cmd);
        try {
            inventoryService.reserveStock(orderId, cmd.getItems());
            paymentService.processPayment(orderId, cmd.getPaymentDetails());
            orderService.completeOrder(orderId);
        } catch (PaymentFailedException ex) {
            // Compensating Transactions
            inventoryService.releaseStock(orderId);
            orderService.cancelOrder(orderId);
        }
    }
}
